/* ------------------------------ ingress ------------------------------ */

static void handle_data(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t p = info->p;
    if (p < c->b) {
        c->n_stale++;
        c->repeat[rank] = 1;
        return;
    }
    if (p >= c->b + c->N) {
        c->n_blocked++;
        return;
    }
    uint32_t idx = p % c->N;
    slot_t *s = &c->slots[idx];
    if (s->in_use && s->p != p) {
        c->n_overwrite++;
        free_slot(c, s);
    }
    if (!s->in_use) {
        memset(s, 0, sizeof(*s));
        s->p = p;
        s->in_use = 1;
        c->occupied++;
    }
    uint8_t bit = (uint8_t)(1u << rank);
    if (s->mask & bit) {
        c->n_dup++;
        c->repeat[rank] = 1;
        return;
    }
    uint8_t *copy = NULL;
    if (c->primitive == P_ALLGATHER) {
        copy = malloc(c->plen ? c->plen : 1u);
        if (!copy) {
            return;
        }
        memcpy(copy, info->payload, c->plen);
        s->g[rank] = copy;
    } else if (c->primitive == P_BCAST) {
        memcpy(slot_payload(c, p), info->payload, c->plen);
    } else {
        uint32_t *accum = (uint32_t *)slot_payload(c, p);
        const uint8_t *raw = info->payload;
        if (s->mask == 0) {
            for (uint32_t j = 0; j < c->D; j++) {
                accum[j] = ((uint32_t)raw[4 * j] << 24) | ((uint32_t)raw[4 * j + 1] << 16) |
                           ((uint32_t)raw[4 * j + 2] << 8) | (uint32_t)raw[4 * j + 3];
            }
        } else {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v = ((uint32_t)raw[4 * j] << 24) | ((uint32_t)raw[4 * j + 1] << 16) |
                             ((uint32_t)raw[4 * j + 2] << 8) | (uint32_t)raw[4 * j + 3];
                accum[j] += v;
            }
        }
    }
    s->mask |= bit;
    s->complete = (s->mask == c->need_mask) ? 1u : 0u;
    c->n_accepted++;
    if (p == c->R[rank]) {
        while (c->R[rank] < c->K) {
            slot_t *t = slot_of(c, c->R[rank]);
            if (!t || !(t->mask & bit)) {
                break;
            }
            c->R[rank]++;
        }
    }
}

static void handle_ack(collector_t *c, int rank, const rx_info_t *info) {
    uint32_t prefix = (info->psn - c->start + 1u) & M24;
    if (prefix > c->acked[rank] && prefix <= c->S[rank]) {
        c->acked[rank] = prefix;
    } else {
        c->n_ack_ignored++;
    }
}

static void ingress_frame(collector_t *c, int rank, const uint8_t *frame, size_t len) {
    rx_info_t info;
    if (!wire_valid(c, frame, len, &info)) {
        c->n_wire++;
        return;
    }
    if (!endpoint_valid(c, rank, frame, &info)) {
        c->n_endpoint++;
        return;
    }
    if (info.is_ack) {
        c->n_rx_ack++;
        handle_ack(c, rank, &info);
    } else {
        c->n_rx_data++;
        handle_data(c, rank, &info);
    }
    service(c, false, -1);
}

