static void build_payload_words(const collector_t *c, uint32_t seed, uint32_t p, int rank,
                                uint8_t *dst) {
    for (uint32_t j = 0; j < c->D; j++) {
        uint32_t v = seed + 0x9e3779b9u * (p + 1u) + 0x85ebca6bu * (uint32_t)(rank + 1) +
                     0xc2b2ae35u * (j + 1u);
        dst[4 * j] = (uint8_t)(v >> 24);
        dst[4 * j + 1] = (uint8_t)(v >> 16);
        dst[4 * j + 2] = (uint8_t)(v >> 8);
        dst[4 * j + 3] = (uint8_t)v;
    }
}

